{
  "references": [
    {
      "id": "R1",
      "summary_ko": "여성의 손에 두 개의 유리잔이 있음."
    },
    {
      "id": "R2",
      "summary_ko": "여성이 천을 집어 들 때 천이 나타났다가 사라짐."
    },
    {
      "id": "R3",
      "summary_ko": "물을 마시던 사람이 잔 하나를 내려놓자 유리잔이 사라짐."
    },
    {
      "id": "R4",
      "summary_ko": "유리잔이 창문 닦는 걸레/천으로 변함."
    }
  ],
  "candidates": [
    {
      "id": "C1",
      "summary_ko": "카운터에 놓인 유리잔이 청소용 천으로 변함."
    }
  ],
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "R1은 손에 들린 두 개의 잔을 기술하고, C1은 잔이 청소용 천으로 변형되는 이상 현상을 기술하여 서로 다릅니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "R2는 천이 나타났다 사라지는 현상을 기술하며, C1은 유리잔이 천으로 형태가 변하는 현상을 기술하므로 대상과 결함이 다릅니다."
    },
    {
      "reference_id": "R3",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "R3는 내려놓은 잔이 완전히 사라지는 현상이고, C1은 잔이 청소용 천으로 변형되는 현상이라 결함 내용이 다릅니다."
    },
    {
      "reference_id": "R4",
      "candidate_id": "C1",
      "verdict": "same",
      "reason_ko": "두 설명 모두 유리잔이 청소용 천(걸레)으로 변형되는 동일한 이상 현상을 기술하고 있습니다."
    }
  ]
}
